1	import { DEFAULT_ITEMS, MAX_QTY, MIN_QTY, formatMoney, lineTotal, subtotal, increment, decrement, promoRate, discountFor } from './cart.js';
2	
3	const STORAGE_KEY = 'cart:v1';
4	
5	const state = {
6	  items: load(),
7	  discount: 0, // cents, set when a promo code is applied
8	  promoError: '',
9	};
10	
11	function load() {
12	  try {
13	    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
14	    if (Array.isArray(saved)) return saved;
15	  } catch {}
16	  return structuredClone(DEFAULT_ITEMS);
17	}
18	
19	function save() {
20	  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state.items)); } catch {}
21	}
22	
23	const $ = (sel) => document.querySelector(sel);
24	
25	function renderLine(item) {
26	  const li = document.createElement('li');
27	  li.className = 'line';
28	  li.innerHTML = `
29	    <div class="line-name">${item.name}<span class="sku">${item.sku}</span></div>
30	    <div class="stepper">
31	      <button type="button" class="dec" aria-label="Decrease quantity" ${item.qty < MIN_QTY ? 'disabled' : ''}>−</button>
32	      <output class="qty" aria-live="polite">${item.qty}</output>
33	      <button type="button" class="inc" aria-label="Increase quantity" ${item.qty > MAX_QTY ? 'disabled' : ''}>+</button>
34	    </div>
35	    <div class="line-total">${formatMoney(lineTotal(item))}</div>
36	    <button type="button" class="remove">Remove</button>`;
37	  li.querySelector('.inc').addEventListener('click', () => { increment(item); render(); });
38	  li.querySelector('.dec').addEventListener('click', () => { decrement(item); render(); });
39	  li.querySelector('.remove').addEventListener('click', () => {
40	    state.items = state.items.filter((x) => x !== item);
41	    save();
42	    render();
43	  });
44	  return li;
45	}
46	
47	function render() {
48	  const list = $('#lines');
49	  list.replaceChildren(...state.items.map(renderLine));
50	  const empty = state.items.length === 0;
51	  $('#empty').hidden = !empty;
52	  $('#summary').classList.toggle('is-hidden', empty);
53	
54	  const sub = subtotal(state.items);
55	  $('#subtotal').textContent = formatMoney(sub);
56	  $('#discount-row').hidden = state.discount === 0;
57	  $('#discount').textContent = '−' + formatMoney(state.discount);
58	  $('#total').textContent = formatMoney(sub - state.discount);
59	  $('#promo-error').textContent = state.promoError;
60	  $('#promo-error').hidden = !state.promoError;
61	}
62	
63	$('#promo-form').addEventListener('submit', (e) => {
64	  e.preventDefault();
65	  const rate = promoRate($('#promo').value);
66	  if (rate === null) {
67	    state.promoError = 'Code not recognised';
68	  } else {
69	    state.discount = discountFor(state.items, rate);
70	  }
71	  render();
72	});
73	
74	render();
