import { chromium } from 'playwright-core';

const base = 'http://127.0.0.1:4173/';
const browser = await chromium.launch();

async function freshPage(viewport = { width: 1280, height: 900 }) {
  const page = await browser.newPage({ viewport });
  await page.addInitScript(() => localStorage.clear());
  await page.goto(base);
  return page;
}

// 1. Stepper boundary: click + eleven times on line 2 (monitor, qty 1), check max
{
  const page = await freshPage();
  const line = page.locator('.line').nth(1);
  for (let i = 0; i < 12; i++) await line.locator('.inc').click();
  const qty = await line.locator('.qty').innerText();
  const incDisabled = await line.locator('.inc').isDisabled();
  console.log('STEPPER MAX: qty after 12 clicks =', qty, 'inc disabled?', incDisabled);
  await page.close();
}

// 2. Stepper min boundary
{
  const page = await freshPage();
  const line = page.locator('.line').nth(0); // keyboard qty 1
  for (let i = 0; i < 3; i++) await line.locator('.dec').click();
  const qty = await line.locator('.qty').innerText();
  const decDisabled = await line.locator('.dec').isDisabled();
  console.log('STEPPER MIN: qty after 3 dec clicks (start 1) =', qty, 'dec disabled?', decDisabled);
  await page.close();
}

// 3. Money format thousands separator (default subtotal is $1,053.00)
{
  const page = await freshPage();
  const sub = await page.locator('#subtotal').innerText();
  console.log('MONEY FORMAT: subtotal text =', JSON.stringify(sub));
  await page.close();
}

// 4. Promo error clears on valid code after invalid
{
  const page = await freshPage();
  await page.fill('#promo', 'NOPE');
  await page.click('#promo-form button[type=submit]');
  const err1 = await page.locator('#promo-error').isHidden();
  await page.fill('#promo', 'SAVE10');
  await page.click('#promo-form button[type=submit]');
  const errVisible = await page.locator('#promo-error').isVisible();
  const errText = await page.locator('#promo-error').innerText().catch(() => '');
  console.log('PROMO CLEAR: error hidden after invalid?', err1, '| error still visible after valid code applied?', errVisible, JSON.stringify(errText));
  await page.close();
}

// 5. Discount follows later quantity changes
{
  const page = await freshPage();
  await page.fill('#promo', 'SAVE10');
  await page.click('#promo-form button[type=submit]');
  const discountBefore = await page.locator('#discount').innerText();
  const line = page.locator('.line').nth(0);
  await line.locator('.inc').click();
  await line.locator('.inc').click();
  const discountAfter = await page.locator('#discount').innerText();
  console.log('DISCOUNT FOLLOWS QTY: before=', discountBefore, 'after +2 qty=', discountAfter, '(should differ)');
  await page.close();
}

// 6. Persistence of quantity change across reload
{
  const page = await freshPage();
  const line = page.locator('.line').nth(0);
  await line.locator('.inc').click();
  await line.locator('.inc').click();
  const qtyBeforeReload = await line.locator('.qty').innerText();
  await page.reload();
  const qtyAfterReload = await page.locator('.line').nth(0).locator('.qty').innerText();
  console.log('PERSISTENCE: qty before reload=', qtyBeforeReload, 'qty after reload=', qtyAfterReload);
  await page.close();
}

// 7. Layout: 375px horizontal scroll + checkout visibility
{
  const page = await freshPage({ width: 375, height: 700 });
  const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
  const clientWidth = await page.evaluate(() => document.documentElement.clientWidth);
  const checkoutBox = await page.locator('.checkout').boundingBox();
  console.log('LAYOUT 375px: scrollWidth=', scrollWidth, 'clientWidth=', clientWidth, 'horizontal overflow?', scrollWidth > clientWidth, 'checkout box=', checkoutBox);
  await page.screenshot({ path: '/tmp/cart-375.png', fullPage: true });
  await page.close();
}

// 8. Layout: exactly 768px should be two-column per spec
{
  const page = await freshPage({ width: 768, height: 900 });
  const cartFlexDirection = await page.evaluate(() => getComputedStyle(document.querySelector('.cart')).flexDirection);
  console.log('LAYOUT 768px: .cart flex-direction =', cartFlexDirection, '(spec wants row/two-column at >=768px)');
  await page.close();
}

// 9. Empty state hides summary including checkout
{
  const page = await freshPage();
  for (let i = 0; i < 3; i++) {
    await page.locator('.line').first().locator('.remove').click();
  }
  const emptyVisible = await page.locator('#empty').isVisible();
  const summaryVisible = await page.locator('#summary').isVisible();
  const checkoutVisible = await page.locator('.checkout').isVisible();
  const summaryBox = await page.locator('#summary').boundingBox();
  console.log('EMPTY STATE: empty msg visible?', emptyVisible, 'summary visible (Playwright)?', summaryVisible, 'checkout visible (Playwright)?', checkoutVisible, 'summary boundingBox=', summaryBox);
  await page.close();
}

await browser.close();

